def transform(text, upper=False, reverse=False):
    if upper:
        text = text.upper()
    if reverse:
        text = text[::-1]
    return text

def main(argv=None):
    import argparse, inspect
    parser=argparse.ArgumentParser()
    parser.add_argument('--upper',action='store_true')
    parser.add_argument('--reverse',action='store_true')
    parser.add_argument('text',nargs='+')
    args=parser.parse_args(argv)
    params=inspect.signature(transform).parameters
    kwargs={}
    if 'upper' in params: kwargs['upper']=args.upper
    if 'reverse' in params: kwargs['reverse']=args.reverse
    print(transform(' '.join(args.text),**kwargs))


if __name__=='__main__':
    main()
